  ('VS_COGNITIVE_IMPAIRMENT_OR_DEMENTIA', 'http://hl7.org/fhir/sid/icd-10-cm', 'G30.9'),
  ('VS_COGNITIVE_IMPAIRMENT_OR_DEMENTIA', 'http://hl7.org/fhir/sid/icd-10-cm', 'G31.84'),
  ('VS_MEMORY_CLINIC_VISIT', 'https://trialbox.local/fhir/CodeSystem/department', 'NEUR'),
  ('VS_MEMORY_CLINIC_VISIT', 'https://trialbox.local/fhir/CodeSystem/department', 'PSY')),
vsf(vs_id, system, prefix) AS (VALUES
  ('VS_COGNITIVE_IMPAIRMENT_OR_DEMENTIA', 'http://hl7.org/fhir/sid/icd-10', 'F00'),
  ('VS_COGNITIVE_IMPAIRMENT_OR_DEMENTIA', 'http://hl7.org/fhir/sid/icd-10-cm', 'F01'),
  ('VS_COGNITIVE_IMPAIRMENT_OR_DEMENTIA', 'http://hl7.org/fhir/sid/icd-10-cm', 'F02'),
  ('VS_COGNITIVE_IMPAIRMENT_OR_DEMENTIA', 'http://hl7.org/fhir/sid/icd-10-cm', 'F03'),
  ('VS_COGNITIVE_IMPAIRMENT_OR_DEMENTIA', 'http://hl7.org/fhir/sid/icd-10-cm', 'G30')),
a_neur_coh_inc_01_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_COGNITIVE_IMPAIRMENT_OR_DEMENTIA' AND vs.system = x.system AND vs.code = x.code)) e ON e.pid = b.pid AND e.d <= b.index_date
  GROUP BY b.pid, b.index_date),
a_neur_coh_inc_01_1_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_COGNITIVE_IMPAIRMENT_OR_DEMENTIA' AND vs.system = x.system AND vs.code = x.code) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_COGNITIVE_IMPAIRMENT_OR_DEMENTIA' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_COGNITIVE_IMPAIRMENT_OR_DEMENTIA' AND vs.system = x.system AND vs.code = x.code)))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
a_neur_coh_inc_01_1_off AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_COGNITIVE_IMPAIRMENT_OR_DEMENTIA' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_COGNITIVE_IMPAIRMENT_OR_DEMENTIA' AND vs.system = x.system AND vs.code = x.code))) e ON e.pid = b.pid AND e.d <= b.index_date
  GROUP BY b.pid, b.index_date),
-- NEUR-COH-INC-01 (inclusion): 軽度認知障害（MCI）または認知症（アルツハイマー型、血管性、その他）と診断されている者（ICD-10-CM G31.84、G30、F01〜F03）。
c_neur_coh_inc_01 AS (
  SELECT b.pid, b.index_date, (CASE WHEN (coalesce(a_neur_coh_inc_01_1.n, 0) > 0) THEN TRUE WHEN coalesce(a_neur_coh_inc_01_1_off.n, 0) > 0 THEN NULL WHEN (coalesce(a_neur_coh_inc_01_1_nd.n, 0) > 0) THEN NULL ELSE FALSE END) AS v,
         concat_ws(';', coalesce(a_neur_coh_inc_01_1.ev, a_neur_coh_inc_01_1_off.ev, a_neur_coh_inc_01_1_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_neur_coh_inc_01_1 ON a_neur_coh_inc_01_1.pid = b.pid AND a_neur_coh_inc_01_1.index_date = b.index_date
  LEFT JOIN a_neur_coh_inc_01_1_nd ON a_neur_coh_inc_01_1_nd.pid = b.pid AND a_neur_coh_inc_01_1_nd.index_date = b.index_date
  LEFT JOIN a_neur_coh_inc_01_1_off ON a_neur_coh_inc_01_1_off.pid = b.pid AND a_neur_coh_inc_01_1_off.index_date = b.index_date),
a_neur_coh_inc_02_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, eid AS rid, start::DATE AS d FROM encounter x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_MEMORY_CLINIC_VISIT' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/department' AND vs.code = x.dept)) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -365) AND b.index_date
  GROUP BY b.pid, b.index_date),
a_neur_coh_inc_02_1_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, eid AS rid, start::DATE AS d FROM encounter x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_MEMORY_CLINIC_VISIT' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/department' AND vs.code = x.dept))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
-- NEUR-COH-INC-02 (inclusion): 過去12か月以内にもの忘れ外来（脳神経内科または精神科）を1回以上受診した者。
c_neur_coh_inc_02 AS (
  SELECT b.pid, b.index_date, (CASE WHEN (coalesce(a_neur_coh_inc_02_1.n, 0) >= 1) THEN TRUE WHEN (coalesce(a_neur_coh_inc_02_1.n, 0) + coalesce(a_neur_coh_inc_02_1_nd.n, 0) >= 1) THEN NULL ELSE FALSE END) AS v,
         concat_ws(';', coalesce(a_neur_coh_inc_02_1.ev, a_neur_coh_inc_02_1_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_neur_coh_inc_02_1 ON a_neur_coh_inc_02_1.pid = b.pid AND a_neur_coh_inc_02_1.index_date = b.index_date
  LEFT JOIN a_neur_coh_inc_02_1_nd ON a_neur_coh_inc_02_1_nd.pid = b.pid AND a_neur_coh_inc_02_1_nd.index_date = b.index_date),
-- NEUR-COH-INC-03 (inclusion): 登録時の年齢が40歳以上の者。
c_neur_coh_inc_03 AS (
  SELECT b.pid, b.index_date, ((date_sub('year', b.birth_date, b.index_date) >= 40)) AS v,
         concat_ws(';', NULL) AS ev
  FROM base b
  )
SELECT b.pid, b.index_date,
  c_neur_coh_inc_01.v AS "C_NEUR-COH-INC-01", c_neur_coh_inc_01.ev AS "E_NEUR-COH-INC-01",
  c_neur_coh_inc_02.v AS "C_NEUR-COH-INC-02", c_neur_coh_inc_02.ev AS "E_NEUR-COH-INC-02",
  c_neur_coh_inc_03.v AS "C_NEUR-COH-INC-03", c_neur_coh_inc_03.ev AS "E_NEUR-COH-INC-03"
FROM base b
LEFT JOIN c_neur_coh_inc_01 ON c_neur_coh_inc_01.pid = b.pid AND c_neur_coh_inc_01.index_date = b.index_date
LEFT JOIN c_neur_coh_inc_02 ON c_neur_coh_inc_02.pid = b.pid AND c_neur_coh_inc_02.index_date = b.index_date
LEFT JOIN c_neur_coh_inc_03 ON c_neur_coh_inc_03.pid = b.pid AND c_neur_coh_inc_03.index_date = b.index_date
ORDER BY b.pid, b.index_date
